def _folder_program(profile_dir: str, baseline_path: str = "") -> str:
    """The folder listing program for ``profile_dir`` (plus an optional baseline file)."""
    return (_FOLDER_PROGRAM.replace("__PROFILE_DIR__", repr(profile_dir))
            .replace("__BASELINE_PATH__", repr(baseline_path)))


_RULES_PROGRAM = r'''
import json
import re
from pathlib import Path

paths = __PATHS__
# msgFilterRules.dat holds one key="value" pair per line (quotes and backslashes
# escaped with a backslash).  After the version=/logging= header every filter
# starts at its name= line and owns the lines up to the next name= line:
# enabled=, type=, one or more action= lines (each optionally followed by its
# actionValue= or customId=), and condition=.
attribute = re.compile(r'^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*"((?:[^"\\]|\\.)*)"\s*$')


def unescape(value):
    return re.sub(r'\\(.)', r'\1', value)


result = {"files": [], "rules": [], "errors": []}
for raw in paths:
    path = Path(str(raw)).expanduser()
    entry = {"path": str(path), "exists": path.is_file(), "rule_lines": 0, "error": None}
    if path.is_file():
        try:
            text = path.read_text(encoding="utf-8", errors="replace")
        except OSError as exc:
            entry["error"] = "%s: %s" % (type(exc).__name__, exc)
        else:
            rule = None
            for line in text.splitlines():
                match = attribute.match(line)
                if not match:
                    continue
                key, value = match.group(1), unescape(match.group(2))
                if key == "name":
                    rule = {"name": value, "actions": [], "__source__": str(path)}
                    result["rules"].append(rule)
                    entry["rule_lines"] += 1
                elif rule is None:
                    continue
                elif key == "action":
                    rule["actions"].append({"action": value})
                elif key in ("actionValue", "customId") and rule["actions"]:
                    rule["actions"][-1].setdefault(key, value)
                else:
                    rule.setdefault(key, value)
            for parsed in result["rules"]:
                if parsed.get("__source__") == str(path) and parsed["actions"]:
                    # The first action stays readable under the flat keys.
                    parsed.setdefault("action", parsed["actions"][0].get("action"))
                    parsed.setdefault("actionValue", parsed["actions"][0].get("actionValue"))
    else:
        result["errors"].append("rule file is absent: " + str(path))
    result["files"].append(entry)
print(json.dumps(result, ensure_ascii=False))
'''

# OSWorld's ``close_window`` postconfig (``wmctrl -c``/``-Fc``/``-xc``): close the
# matching windows through the window manager, which runs the application's own
# close path, then wait until they are gone.
_CLOSE_WINDOW_PROGRAM = r'''
import json
import os
import subprocess
import time

name = __NAME__
strict = __STRICT__
by_class = __BY_CLASS__
wait_seconds = __WAIT__
os.environ.setdefault("DISPLAY", ":0")
xauthority = os.path.expanduser("~/.Xauthority")
if "XAUTHORITY" not in os.environ and os.path.exists(xauthority):
    os.environ["XAUTHORITY"] = xauthority
result = {"window_name": name, "strict": strict, "by_class": by_class, "matched": [], "still_open": [], "error": None}


def matching():
    listing = subprocess.run(["wmctrl", "-lx" if by_class else "-l"], capture_output=True, text=True, timeout=10)
    ids = []
    for line in listing.stdout.splitlines():
        parts = line.split(None, 4 if by_class else 3)
        if len(parts) < 2:
            continue
        if by_class:
            label = parts[2] if len(parts) > 2 else ""
        else:
            label = parts[3] if len(parts) > 3 else ""
        if (label == name) if strict else (name.casefold() in label.casefold()):
            ids.append(parts[0])
    return ids


try:
    ids = matching()
    result["matched"] = ids
    for window_id in ids:
        subprocess.run(["wmctrl", "-ic", window_id], capture_output=True, timeout=10)
    remaining = list(ids)
    deadline = time.time() + wait_seconds
    while remaining and time.time() < deadline:
        time.sleep(0.5)
        current = set(matching())
        remaining = [window_id for window_id in ids if window_id in current]
    result["still_open"] = remaining
except FileNotFoundError:
    result["error"] = "wmctrl is not installed"
except Exception as exc:
    result["error"] = "%s: %s" % (type(exc).__name__, exc)
print(json.dumps(result, ensure_ascii=False))
'''

# nsMsgFilterType bits of a filter's type= attribute (the "Apply filter when" triggers).
FILTER_TYPE_FLAGS = {
    "new_mail": 0x01,
    "manual": 0x10,
    "after_junk": 0x20,
    "after_sending": 0x40,
    "archive": 0x80,
    "periodic": 0x100,
}
# One search term of a condition= value: "OR (subject,contains,invoice64)", a
# quoted value may hold parentheses; "ALL" matches every message.
_CONDITION_TERM = re.compile(r'(?:AND|OR)\s*\((?:[^()"]|"(?:[^"\\]|\\.)*")*\)|\bALL\b', re.IGNORECASE)


def _run_program(controller: Any, program: str, timeout: int) -> dict[str, Any]:
    if controller is None or not hasattr(controller, "run_python_script"):
        raise RuntimeError("controller.run_python_script is required")
    raw = controller.run_python_script(program, timeout=timeout)
    if not isinstance(raw, Mapping):
        raise RuntimeError("runtime returned no result mapping")
    output = str(raw.get("stdout") or raw.get("output") or "").strip()
    if int(raw.get("returncode", -1)) != 0:
        raise RuntimeError(str(raw.get("stderr") or "") or output or "runtime command failed")
    try:
        return dict(json.loads(output.splitlines()[-1]))
    except (ValueError, IndexError) as exc:
        raise RuntimeError("runtime output was not JSON: %s" % exc) from exc


class ThunderbirdFolderCalendarEvaluator(BaseEvaluator):
    """Verify a required mail folder and a required calendar event title."""

    PASS_MESSAGE = "Thunderbird folder and calendar checks passed"
    FAIL_MESSAGE = "Thunderbird folder and calendar checks failed"

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        timeout = int(params.get("timeout", DEFAULT_TIMEOUT) or DEFAULT_TIMEOUT)
        profile_dir = str(params.get("profile_dir") or DEFAULT_PROFILE_DIR)
        required_folder = str(params.get("required_folder") or "").strip()
        required_event_title = str(params.get("required_event_title") or "").strip()
        seed_folders = [str(item) for item in (params.get("expected_seed_folders") or [])]
        require_seed_folders = bool(params.get("require_seed_folders", False))
        baseline_path = str(params.get("seed_folder_baseline_path") or "").strip()
        if not required_folder and not required_event_title:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="the task declares neither a required mail folder nor a required event title",
            )

        controller = context.get("controller")
        try:
            folders = _run_program(controller, _folder_program(profile_dir, baseline_path), timeout)
        except Exception as exc:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="Thunderbird mail folders could not be read: %s: %s" % (type(exc).__name__, exc),
            )

        checks: list[dict[str, Any]] = []
        observed_folders = [str(name) for name in folders.get("folders") or []]
        top_level_folders = [str(name) for name in folders.get("top_level_folders") or []]
        baseline = folders.get("baseline_folders")
        baseline_folders = (
            {str(name) for name in baseline} if isinstance(baseline, list) else None
        )

        for name in seed_folders:
            # The brief says the existing folders "must remain in place", so a seed
            # folder that the initializer saw directly under Local Folders must still
            # be there (not deleted, moved into Trash or under another folder).  A
            # seed folder the snapshot never had is not the agent's doing: the
            # task's verifier_rules (tasks/v1/linux/
            # thunderbird_qa66_mail_folder_search_calendar.yaml) keep that case
            # diagnostic, as is every seed folder when no baseline was recorded.
            seeded = baseline_folders is not None and name in baseline_folders
            if seeded:
                present = name in top_level_folders
            else:
                present = name in observed_folders
            check = {
                "check_id": "seed_folder:%s" % name,
                "passed": present,
                "expected": {"folder": name, "present": True,
                             "in_place": seeded},
                "observed": {"present": present,
                             "in_initial_state": None if baseline_folders is None else seeded},
            }
            if not (require_seed_folders or seeded):
                check["diagnostic"] = True
            checks.append(check)

        if required_folder:
            present = required_folder in observed_folders
            checks.append(
                {
                    "check_id": "folder:%s" % required_folder,
                    "passed": present,
                    "expected": {"folder": required_folder, "present": True},
                    "observed": {"folders": observed_folders},
                }
            )

        calendar_evidence: dict[str, Any] = {}
        if required_event_title:
            try:
                calendar_evidence = read_calendar_evidence(
                    controller,
                    {"profile_dir": profile_dir, "timeout": timeout},
                )
            except Exception as exc:
                calendar_evidence = {"error": "%s: %s" % (type(exc).__name__, exc)}
            titles = self._calendar_titles(calendar_evidence)
            present = required_event_title in titles
            checks.append(
                {
                    "check_id": "event_title:%s" % required_event_title,
                    "passed": present,
                    "expected": {"title": required_event_title, "present": True},
                    "observed": {"matching_title_present": present, "event_count": len(titles)},
                }
            )

        failed = [
            check["check_id"]
            for check in checks
            if not check["passed"] and not check.get("diagnostic")
        ]
        diagnostic_failures = [
            check["check_id"]
            for check in checks
            if not check["passed"] and check.get("diagnostic")
        ]
        metadata = {
            "profile_dir": folders.get("profile_dir"),
            "local_folders_dir": folders.get("local_folders_dir"),
            "folders": observed_folders,
            "folder_errors": folders.get("errors"),
            "calendar_error": calendar_evidence.get("error") or calendar_evidence.get("calendar_error"),
            "checks": checks,
            "failures": failed,
            "diagnostic_failures": diagnostic_failures,
            "require_seed_folders": require_seed_folders,
            "top_level_folders": top_level_folders,
            "seed_folder_baseline": None if baseline_folders is None else sorted(baseline_folders),
            "seed_folder_baseline_error": folders.get("baseline_error"),
        }
        if not checks:
            return EvalResult(status=EvalStatus.FAIL, message="no folder or calendar requirement was comparable", metadata=metadata)
        if failed:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="Thunderbird folder and calendar checks failed: %s" % ", ".join(failed[:8]),
                metadata=metadata,
            )
        return EvalResult(status=EvalStatus.PASS, message=self.PASS_MESSAGE, metadata=metadata)

    @staticmethod
    def _calendar_titles(evidence: Mapping[str, Any]) -> list[str]:
        titles: list[str] = []
        for profile in evidence.get("profiles") or []:
            if not isinstance(profile, Mapping):
                continue
            for event in profile.get("events") or []:
                if isinstance(event, Mapping):
                    titles.append(str(event.get("title") or "").strip())
        return titles


class ThunderbirdTaskEvaluator(BaseEvaluator):
    """Verify the message-filter rules stored in the profile."""

    PASS_MESSAGE = "Thunderbird filter checks passed"
    FAIL_MESSAGE = "Thunderbird filter checks failed"

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        contract = params.get("osworld_evaluator")
        timeout = int(params.get("timeout", DEFAULT_TIMEOUT) or DEFAULT_TIMEOUT)
        if not isinstance(contract, Mapping):
            return EvalResult(status=EvalStatus.FAIL, message="the task declares no filter-rule contract")

        declared_path = str(((contract.get("result") or {}) if isinstance(contract.get("result"), Mapping) else {}).get("path") or "").strip()
        expected = contract.get("expected")
        expectations: list[Any] = []
        if isinstance(expected, Mapping):
            rules = expected.get("rules")
            if isinstance(rules, Mapping):
                expectations = list(rules.get("expect") or [])
        if not expectations:
            return EvalResult(status=EvalStatus.FAIL, message="the task declares no expected filter rules")

        controller = context.get("controller")
        # Thunderbird writes msgFilterRules.dat when the Message Filters window
        # closes; the contract's postconfig closes it before anything is read.
        postconfig = self._run_postconfig(controller, contract.get("postconfig"), timeout)

        paths = self._rule_paths(declared_path, params)
        try:
            observed = _run_program(
                controller,
                _RULES_PROGRAM.replace("__PATHS__", repr(paths)),
                timeout,
            )
        except Exception as exc:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="Thunderbird filter rules could not be read: %s: %s" % (type(exc).__name__, exc),
                metadata={"postconfig": postconfig},
            )

        rules = [dict(rule) for rule in (observed.get("rules") or []) if isinstance(rule, Mapping)]
        checks: list[dict[str, Any]] = []
        for index, expectation in enumerate(expectations, start=1):
            if not isinstance(expectation, Mapping):
                continue
            matches = [rule for rule in rules if self._rule_matches(rule, expectation)]
            label = str(expectation.get("actionValue") or expectation.get("action") or "rule_%d" % index)
            checks.append(
                {
                    "check_id": "filter_rule:%s" % label,
                    "passed": bool(matches),
                    "expected": dict(expectation),
                    "observed": [
                        {
                            "name": rule.get("name"),
                            "enabled": rule.get("enabled"),
                            "type": rule.get("type"),
                            "action": rule.get("action"),
                            "actionValue": rule.get("actionValue"),
                            "actions": rule.get("actions"),
                            "condition": rule.get("condition"),
                            "source": rule.get("__source__"),
                        }
                        for rule in matches[:3]
                    ],
                }
            )

        required_folders = [str(item).strip() for item in (params.get("required_folders") or []) if str(item).strip()]
        folder_evidence: dict[str, Any] = {}
        if required_folders:
            profile_dir = self._profile_dir(declared_path, params)
            try:
                folder_evidence = _run_program(controller, _folder_program(profile_dir), timeout)
            except Exception as exc:
                folder_evidence = {"errors": ["%s: %s" % (type(exc).__name__, exc)]}
            observed_folders = [str(name) for name in folder_evidence.get("folders") or []]
            for name in required_folders:
                checks.append(
                    {
                        "check_id": "folder:%s" % name,
                        "passed": name in observed_folders,
                        "expected": {"folder": name, "present": True},
                        "observed": {"folders": observed_folders},
                    }
                )

        failed = [check["check_id"] for check in checks if not check["passed"]]
        metadata = {
            "postconfig": postconfig,
            "paths": paths,
            "files": observed.get("files"),
            "rules": rules,
            "file_errors": observed.get("errors"),
            "checks": checks,
            "failures": failed,
        }
        if required_folders:
            metadata["folders"] = folder_evidence.get("folders")
            metadata["folder_errors"] = folder_evidence.get("errors")
        if not checks:
            return EvalResult(status=EvalStatus.FAIL, message="no filter rule was comparable", metadata=metadata)
        if failed:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="Thunderbird filter checks failed: %s" % ", ".join(failed[:8]),
                metadata=metadata,
            )
        return EvalResult(status=EvalStatus.PASS, message=self.PASS_MESSAGE, metadata=metadata)

    @staticmethod
    def _run_postconfig(controller: Any, steps: Any, timeout: int) -> list[dict[str, Any]]:
        """Run the contract's OSWorld postconfig steps (``close_window``, ``sleep``).

        Each step is best effort: a failure is recorded and the evaluation goes on
        with whatever reached the disk.
        """
        results: list[dict[str, Any]] = []
        for step in steps if isinstance(steps, list) else []:
            if not isinstance(step, Mapping):
                continue
            kind = str(step.get("type") or "")
            parameters = step.get("parameters") if isinstance(step.get("parameters"), Mapping) else {}
            if kind == "sleep":
                seconds = max(0.0, min(float(parameters.get("seconds", 0) or 0), 30.0))
                time.sleep(seconds)
                results.append({"type": kind, "seconds": seconds})
            elif kind == "close_window":
                program = (
                    _CLOSE_WINDOW_PROGRAM.replace("__NAME__", repr(str(parameters.get("window_name") or "")))
                    .replace("__STRICT__", repr(bool(parameters.get("strict", False))))
                    .replace("__BY_CLASS__", repr(bool(parameters.get("by_class", False))))
                    .replace("__WAIT__", repr(10))
                )
                try:
                    outcome = _run_program(controller, program, max(timeout, 30))
                except Exception as exc:
                    outcome = {"error": "%s: %s" % (type(exc).__name__, exc)}
                if outcome.get("matched") and not outcome.get("still_open"):
                    time.sleep(1.0)  # the window's unload handler has just written the file
                results.append({"type": kind, **outcome})
            else:
                results.append({"type": kind, "skipped": "unsupported postconfig step"})
        return results

    @staticmethod
    def _profile_dir(declared_path: str, params: Mapping[str, Any]) -> str:
        profile_dir = str(params.get("profile_dir") or "")
        if not profile_dir and declared_path:
            parents = Path(declared_path).parents
            if len(parents) >= 3:
                profile_dir = str(parents[2])
        return profile_dir or DEFAULT_PROFILE_DIR

    @classmethod
    def _rule_paths(cls, declared_path: str, params: Mapping[str, Any]) -> list[str]:
        paths: list[str] = []
        if declared_path:
            paths.append(declared_path)
        profile_dir = cls._profile_dir(declared_path, params)
        candidate = str(Path(profile_dir) / "Mail" / "Local Folders" / "msgFilterRules.dat")
        if candidate not in paths:
            paths.append(candidate)
        return paths

    @staticmethod
    def _normalize(value: Any) -> str:
        return " ".join(str(value if value is not None else "").split()).strip().casefold()

    @classmethod
    def _rule_matches(cls, rule: Mapping[str, Any], expectation: Mapping[str, Any]) -> bool:
        """Whether one parsed filter block satisfies an expectation.

        ``action``/``actionValue`` must match one action of the filter together;
        ``condition`` compares the search terms as a set (the terms of a "Match
        any"/"Match all" filter are order-free); ``type_flags`` lists trigger
        bits (names of ``FILTER_TYPE_FLAGS`` or integers) that ``type`` must have
        set.  Other keys compare the attribute; a list means "one of these".
        """
        for key, wanted in expectation.items():
            if key in ("action", "actionValue"):
                continue
            seen = rule.get(key)
            if key == "type_flags":
                if not cls._has_type_flags(rule.get("type"), wanted):
                    return False
                continue
            if key == "condition":
                options = wanted if isinstance(wanted, (list, tuple)) else [wanted]
                if seen is None or not any(cls._same_condition(seen, item) for item in options):
                    return False
                continue
            if isinstance(wanted, (list, tuple)):
                if not any(cls._normalize(seen) == cls._normalize(item) for item in wanted):
                    return False
                continue
            if seen is None:
                return False
            if cls._normalize(seen) != cls._normalize(wanted):
                return False
        if "action" in expectation or "actionValue" in expectation:
            actions = [item for item in (rule.get("actions") or []) if isinstance(item, Mapping)]
            if not actions:
                actions = [{"action": rule.get("action"), "actionValue": rule.get("actionValue")}]
            if not any(cls._action_matches(action, expectation) for action in actions):
                return False
        return True

    @classmethod
    def _action_matches(cls, action: Mapping[str, Any], expectation: Mapping[str, Any]) -> bool:
        for key in ("action", "actionValue"):
            if key not in expectation:
                continue
            wanted = expectation[key]
            seen = action.get(key)
            options = wanted if isinstance(wanted, (list, tuple)) else [wanted]
            if seen is None or not any(cls._normalize(seen) == cls._normalize(item) for item in options):
                return False
        return True

    @classmethod
    def _condition_terms(cls, value: Any) -> list[str]:
        text = str(value if value is not None else "")
        terms = [cls._normalize(term) for term in _CONDITION_TERM.findall(text)]
        return sorted(terms) if terms else [cls._normalize(text)]

    @classmethod
    def _same_condition(cls, seen: Any, wanted: Any) -> bool:
        return cls._condition_terms(seen) == cls._condition_terms(wanted)

    @staticmethod
    def _has_type_flags(seen: Any, wanted: Any) -> bool:
        try:
            value = int(str(seen).strip())
        except (TypeError, ValueError):
            return False
        for flag in wanted if isinstance(wanted, (list, tuple)) else [wanted]:
            bit = FILTER_TYPE_FLAGS.get(str(flag).strip().lower()) if not isinstance(flag, int) else flag
            if bit is None:
                try:
                    bit = int(str(flag).strip(), 0)
                except ValueError:
                    return False
            if value & bit != bit:
                return False
        return True
